def sliding_pair_combine(grid_in, grid_out):
    """
    Try sliding window: output[c] = f(input[c], input[c+1])
    This means output has width = input_width - 1
    """
    h, w_in = len(grid_in), len(grid_in[0])
    w_out = len(grid_out[0])

    if w_in != w_out + 1:
        return False, "Width mismatch"

    result = []
    for r in range(h):
        row = []
        for c in range(w_out):
            val_r = grid_in[r][c]
            val_c = grid_in[r][c+1]
            row.append((val_r, val_c))
        result.append(row)
    return True, result

