    all_rules = {}
    for i, demo in enumerate(demo_list):
        in_g = demo[0]
        out_g = demo[1]
        w_in, w_out = len(in_g[0]), len(out_g[0])

        if w_in != w_out + 1:
            continue

        # Build input->output pairs
        pairs = set()
        outputs = {}
        for r in range(len(in_g)):
            for c in range(w_out):
                key = (in_g[r][c], in_g[r][c+1])
                pairs.add(key)
                outputs[key] = out_g[r][c]

        all_rules[i] = {'input_dims': (w_in, w_out), 'pairs': pairs, 'outputs': outputs}

    # Find common outputs for each pair
    print("Pair mapping analysis:")
    for demo_idx, data in all_rules.items():
        print(f"\nDemo {demo_idx}:")
        for pair, out_val in sorted(data['outputs'].items()):
